=== FILE: tb/tb_mac8.v ===
// Self-checking scoreboard testbench for mac8.
// Reference model written from interface_spec.md (MAC-RESET, MAC-CLEAR,
// MAC-ACC, MAC-HOLD, MAC-SAT, MAC-STICKY), not from the RTL.
// Inputs are driven after the falling edge; outputs are compared at the
// following falling edge, after the rising edge the design samples.
`timescale 1ns / 1ps
module tb_mac8;
    reg         clk = 1'b0;
    reg         rst_n;
    reg         clr;
    reg         en;
    reg  [7:0]  a;
    reg  [7:0]  b;
    wire [23:0] acc;
    wire        sat;

    mac8 dut (
        .clk(clk), .rst_n(rst_n), .clr(clr), .en(en),
        .a(a), .b(b), .acc(acc), .sat(sat)
    );

    always #5 clk = ~clk;

    // ---------------- reference model state ----------------
    reg [23:0] exp_acc;
    reg        exp_sat;
    reg        model_valid;   // becomes 1 at the first reset edge
    reg [31:0] sum32;         // total (24 bits) + product (16 bits) fits easily

    // ---------------- bookkeeping ----------------
    integer pass_cnt;
    integer fail_cnt;
    integer cycle;
    integer i;
    integer k;
    integer done;

    // corner counters: each must be nonzero at the end
    integer c_sat_event;     // flag goes 0 -> 1 through an overflowing add
    integer c_exact_max;     // sum exactly 0xFFFFFF, must not saturate
    integer c_clr_with_en;   // clear offered together with an accumulate
    integer c_sticky;        // flag already 1 across a non-clear, non-reset edge
    integer c_hold;          // en low, clr low, rst_n high
    integer c_rst_with_en;   // reset with en high and a nonzero total

    reg [31:0]      rng;
    reg [8*128-1:0] nonce;

    reg       rr, rc, re;
    reg [7:0] ra, rb;

    // xorshift32, deterministic and portable across simulators
    function [31:0] xs;
        input [31:0] x;
        reg   [31:0] y;
        begin
            y  = x ^ (x << 13);
            y  = y ^ (y >> 17);
            y  = y ^ (y << 5);
            xs = y;
        end
    endfunction

    // Compare DUT outputs with the model; count every comparison.
    task check;
        input       r;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        begin
            if (model_valid) begin
                if ((acc !== exp_acc) || (sat !== exp_sat)) begin
                    fail_cnt = fail_cnt + 1;
                    if (fail_cnt <= 10)
                        $display("MISMATCH cycle %0d: rst_n=%b clr=%b en=%b a=%h b=%h | dut acc=%h sat=%b | model acc=%h sat=%b",
                                 cycle, r, c, e, ia, ib, acc, sat, exp_acc, exp_sat);
                end else begin
                    pass_cnt = pass_cnt + 1;
                end
            end
        end
    endtask

    // Apply one cycle of stimulus, update the model per the spec, then compare.
    task step;
        input       r;
        input       c;
        input       e;
        input [7:0] ia;
        input [7:0] ib;
        begin
            rst_n = r; clr = c; en = e; a = ia; b = ib;
            @(posedge clk);
            cycle = cycle + 1;
            if (!r) begin
                // MAC-RESET: reset wins over everything
                if (model_valid && e && (exp_acc != 24'd0))
                    c_rst_with_en = c_rst_with_en + 1;
                exp_acc     = 24'd0;
                exp_sat     = 1'b0;
                model_valid = 1'b1;
            end else if (model_valid) begin
                if (c) begin
                    // MAC-CLEAR: clear wins over an accumulate at the same edge
                    if (e) c_clr_with_en = c_clr_with_en + 1;
                    exp_acc = 24'd0;
                    exp_sat = 1'b0;
                end else if (e) begin
                    // MAC-ACC with unsigned operands, MAC-SAT above 0xFFFFFF
                    sum32 = {8'd0, exp_acc} + ({24'd0, ia} * {24'd0, ib});
                    if (exp_sat) c_sticky = c_sticky + 1;
                    if (sum32 > 32'h00FFFFFF) begin
                        if (!exp_sat) c_sat_event = c_sat_event + 1;
                        exp_acc = 24'hFFFFFF;
                        exp_sat = 1'b1;
                    end else begin
                        if (sum32 == 32'h00FFFFFF) c_exact_max = c_exact_max + 1;
                        exp_acc = sum32[23:0];
                        // MAC-STICKY: exp_sat keeps its value
                    end
                end else begin
                    // MAC-HOLD: nothing changes
                    c_hold = c_hold + 1;
                    if (exp_sat) c_sticky = c_sticky + 1;
                end
            end
            @(negedge clk);
            check(r, c, e, ia, ib);
        end
    endtask

    // Corner self-check: a corner the run never reached is a failure.
    task corner;
        input integer id;
        input integer n;
        begin
            if (n == 0) begin
                fail_cnt = fail_cnt + 1;
                case (id)
                    0: $display("CORNER NOT REACHED: saturation event");
                    1: $display("CORNER NOT REACHED: exact 0xFFFFFF without saturation");
                    2: $display("CORNER NOT REACHED: clear with accumulate offered");
                    3: $display("CORNER NOT REACHED: sticky flag held");
                    4: $display("CORNER NOT REACHED: hold with en low");
                    5: $display("CORNER NOT REACHED: reset with accumulate offered");
                    default: $display("CORNER NOT REACHED: id %0d", id);
                endcase
            end else begin
                pass_cnt = pass_cnt + 1;
            end
        end
    endtask

    // Print the single verdict line.
    task verdict;
        begin
            $write("NIRMAAN-SIM ");
            for (k = 127; k >= 0; k = k - 1)
                if (nonce[k*8 +: 8] != 8'd0)
                    $write("%c", nonce[k*8 +: 8]);
            $display(" %0d passed, %0d failed", pass_cnt, fail_cnt);
        end
    endtask

    initial begin
        pass_cnt = 0; fail_cnt = 0; cycle = 0; done = 0;
        c_sat_event = 0; c_exact_max = 0; c_clr_with_en = 0;
        c_sticky = 0; c_hold = 0; c_rst_with_en = 0;
        model_valid = 1'b0;
        exp_acc = 24'd0; exp_sat = 1'b0;
        rng = 32'h1234_5678;
        nonce = 0;
        if (!$value$plusargs("nonce=%s", nonce))
          if (!$value$plusargs("NONCE=%s", nonce))
            if (!$value$plusargs("nirmaan_nonce=%s", nonce))
              if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
                if (!$value$plusargs("NIRMAAN_SIM_NONCE=%s", nonce))
                  $display("WARNING: no nonce plusarg found");

        // S1: reset while an accumulate is offered (MAC-RESET), reset with clr high
        step(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b0, 1'b1, 1'b1, 8'hFF, 8'hFF);

        // S2: basic accumulate, zero operands (MAC-ACC)
        step(1'b1, 1'b0, 1'b1, 8'd3,  8'd4);
        step(1'b1, 1'b0, 1'b1, 8'd0,  8'hAB);
        step(1'b1, 1'b0, 1'b1, 8'hCD, 8'd0);
        step(1'b1, 1'b0, 1'b1, 8'd1,  8'd1);

        // S3: operands read as unsigned (a signed reading would differ)
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'h01);
        step(1'b1, 1'b0, 1'b1, 8'h80, 8'h02);
        step(1'b1, 1'b0, 1'b1, 8'h80, 8'h80);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'h7F, 8'h81);

        // S4: hold with en low and nonzero operands (MAC-HOLD)
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b0, 8'h5A, 8'hA5);
        step(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);

        // S5: clear wins over an accumulate (MAC-CLEAR), then clear with en low
        step(1'b1, 1'b1, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b1, 1'b0, 8'h12, 8'h34);

        // S6: reach exactly 0xFFFFFF without saturating, then overflow by one (MAC-SAT)
        for (i = 0; i < 258; i = i + 1)
            step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);       // 258 * 65025 = 16776450
        step(1'b1, 1'b0, 1'b1, 8'd3, 8'hFF);            // + 765 = 0xFFFFFF, sat stays 0
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);           // hold at max
        step(1'b1, 1'b0, 1'b1, 8'd0, 8'd0);             // + 0 at max, still no saturation
        step(1'b1, 1'b0, 1'b1, 8'd1, 8'd1);             // + 1: wrapped would be 0, must saturate

        // S7: flag stays 1 whatever is offered (MAC-STICKY)
        step(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'h00, 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'd1, 8'd0);
        step(1'b1, 1'b0, 1'b0, 8'h00, 8'h00);

        // S8: clear ends sticky, accumulation restarts from zero
        step(1'b1, 1'b1, 1'b0, 8'h00, 8'h00);
        step(1'b1, 1'b0, 1'b1, 8'd2, 8'd3);
        step(1'b1, 1'b0, 1'b1, 8'd5, 8'd7);

        // S9: saturate again, then reset (with accumulate offered) ends sticky
        for (i = 0; i < 260; i = i + 1)
            step(1'b1, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b0, 1'b0, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b0, 8'hFF, 8'hFF);

        // S10: reset in the middle of accumulating, reset together with clr
        step(1'b1, 1'b0, 1'b1, 8'd10, 8'd10);
        step(1'b1, 1'b0, 1'b1, 8'd20, 8'd30);
        step(1'b0, 1'b0, 1'b1, 8'd40, 8'd50);
        step(1'b1, 1'b0, 1'b1, 8'd1,  8'd2);
        step(1'b0, 1'b1, 1'b1, 8'hFF, 8'hFF);
        step(1'b1, 1'b0, 1'b1, 8'd9,  8'd9);

        // S11: seeded random phase, operands biased toward 0xFF so saturation recurs
        for (i = 0; i < 4000; i = i + 1) begin
            rng = xs(rng); rr = (rng[11:0] != 12'd0);       // reset about 1 in 4096
            rng = xs(rng); rc = (rng[10:0] == 11'd0);       // clear about 1 in 2048
            rng = xs(rng); re = (rng[1:0]  != 2'd0);        // en 3 in 4
            rng = xs(rng); ra = (rng[1:0] == 2'd0) ? 8'hFF : rng[15:8];
            rng = xs(rng); rb = (rng[1:0] == 2'd0) ? 8'hFF : rng[15:8];
            step(rr, rc, re, ra, rb);
        end

        // Corner coverage self-check
        corner(0, c_sat_event);
        corner(1, c_exact_max);
        corner(2, c_clr_with_en);
        corner(3, c_sticky);
        corner(4, c_hold);
        corner(5, c_rst_with_en);

        $display("corners: sat=%0d exact_max=%0d clr_en=%0d sticky=%0d hold=%0d rst_en=%0d cycles=%0d",
                 c_sat_event, c_exact_max, c_clr_with_en, c_sticky, c_hold, c_rst_with_en, cycle);

        done = 1;
        verdict;
        $finish;
    end

    // Watchdog: report a failure if the main sequence never completes.
    initial begin
        #1000000;
        if (done == 0) begin
            $display("TIMEOUT: main sequence did not complete");
            fail_cnt = fail_cnt + 1;
            done = 1;
            verdict;
            $finish;
        end
    end
endmodule
=== END FILE ===
